const estado = {
  preferencias: { tema: 'claro', idioma: 'es' },
};
const nuevo = {
  ...estado,
  preferencias: {
    ...estado.preferencias,
    tema: 'oscuro',
  },
};
estado.preferencias.tema + '|' + nuevo.preferencias.tema;

function actualizar(estado, clave, valor) {
  const copia = { ...estado };
  copia.preferencias[clave] = valor;
  return copia;
}

function actualizarPreferencia(estado, clave, valor) {
  estado.preferencias[clave] = valor;
  return estado;
}
